def point_set(intervals):
    pts = set()
    for s, e in intervals:
        pts.update(range(s, e + 1))
    return pts

def reference_merge(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError
    if not intervals:
        return []
    ivs = sorted(intervals)
    out = [ivs[0]]
    for s, e in ivs[1:]:
        ps, pe = out[-1]
        if s <= pe:  # overlap or touch (share a point); adjacent s == pe+1 stays separate
            out[-1] = (ps, max(pe, e))
        else:
            out.append((s, e))
    return out

@given(valid_lists)
def test_property_touching_points_share_output_interval(intervals):
    # any two consecutive integers both covered must lie in same output interval
    out = merge_intervals(list(intervals))
    covered = point_set(intervals)
    for p in list(covered):
        if p + 1 in covered:
            holders_p = [iv for iv in out if iv[0] <= p <= iv[1]]
            holders_q = [iv for iv in out if iv[0] <= p + 1 <= iv[1]]
            assert len(holders_p) == 1
            assert holders_p == holders_q
